// 黄金矿工钩子状态机 - TypeScript实现
// 可直接运行的完整代码

enum HookState {
  IDLE = 'IDLE',           // 待命状态
  SWINGING = 'SWINGING',   // 摆动状态
  SHOOTING = 'SHOOTING',   // 发射状态
  GRABBING = 'GRABBING',   // 抓取中状态
  REELING = 'REELING',     // 回收状态
}

interface Position {
  x: number;
  y: number;
}

interface GameItem {
  id: string;
  position: Position;
  weight: number;
  value: number;
  type: 'gold' | 'rock' | 'diamond' | 'bag';
  width: number;
  height: number;
}

interface HookConfig {
  minAngle: number;      // 最小摆动角度（度）
  maxAngle: number;      // 最大摆动角度（度）
  swingSpeed: number;    // 摆动速度
  shootSpeed: number;    // 发射速度
  baseReelSpeed: number; // 基础回收速度
  maxLength: number;     // 最大钩子长度
}

class HookStateMachine {
  private state: HookState = HookState.IDLE;
  private position: Position = { x: 0, y: 0 };  // 钩子起点（矿工位置）
  private hookEnd: Position = { x: 0, y: 0 };   // 钩子末端位置
  private angle: number = 0;                     // 当前角度
  private length: number = 0;                    // 当前钩子长度
  private swingDirection: number = 1;            // 摆动方向：1或-1
  private grabbedItem: GameItem | null = null;   // 抓取的物品
  private config: HookConfig;
  private stateStartTime: number = 0;
  private listeners: Map<HookState, { onEnter?: () => void; onExit?: () => void }> = new Map();

  constructor(config: Partial<HookConfig> = {}) {
    this.config = {
      minAngle: -75,
      maxAngle: 75,
      swingSpeed: 60,      // 度/秒
      shootSpeed: 300,     // 像素/秒
      baseReelSpeed: 150,  // 像素/秒
      maxLength: 500,
      ...config
    };

    this.setupStateListeners();
    this.transitionTo(HookState.SWINGING);
  }

  // 设置状态监听器
  private setupStateListeners(): void {
    this.listeners.set(HookState.IDLE, {
      onEnter: () => {
        console.log('[IDLE] 钩子进入待命状态');
        this.length = 0;
        this.grabbedItem = null;
      },
      onExit: () => {
        console.log('[IDLE] 钩子离开待命状态');
      }
    });

    this.listeners.set(HookState.SWINGING, {
      onEnter: () => {
        console.log('[SWINGING] 钩子开始摆动');
        this.length = 0;
        this.angle = 0;
      },
      onExit: () => {
        console.log('[SWINGING] 钩子停止摆动，当前角度:', this.angle.toFixed(1));
      }
    });

    this.listeners.set(HookState.SHOOTING, {
      onEnter: () => {
        console.log('[SHOOTING] 钩子发射，角度:', this.angle.toFixed(1));
        this.stateStartTime = Date.now();
      },
      onExit: () => {
        console.log('[SHOOTING] 钩子停止发射，长度:', this.length.toFixed(1));
      }
    });

    this.listeners.set(HookState.GRABBING, {
      onEnter: () => {
        console.log('[GRABBING] 抓取到物品:', this.grabbedItem?.type);
        if (this.grabbedItem) {
          console.log(`  物品信息: 重量=${this.grabbedItem.weight}, 价值=${this.grabbedItem.value}`);
        }
      },
      onExit: () => {
        console.log('[GRABBING] 离开抓取状态');
      }
    });

    this.listeners.set(HookState.REELING, {
      onEnter: () => {
        console.log('[REELING] 开始回收钩子');
        const speed = this.calculateReelSpeed();
        console.log(`  回收速度: ${speed.toFixed(1)} 像素/秒`);
      },
      onExit: () => {
        console.log('[REELING] 回收完成');
        if (this.grabbedItem) {
          console.log(`  成功获取: ${this.grabbedItem.type} (+${this.grabbedItem.value}金币)`);
        }
      }
    });
  }

  // 状态转换
  private transitionTo(newState: HookState): void {
    const oldState = this.state;

    // 执行退出逻辑
    const oldListeners = this.listeners.get(oldState);
    if (oldListeners?.onExit) {
      oldListeners.onExit();
    }

    this.state = newState;
    this.stateStartTime = Date.now();

    // 执行进入逻辑
    const newListeners = this.listeners.get(newState);
    if (newListeners?.onEnter) {
      newListeners.onEnter();
    }

    console.log(`状态转换: ${oldState} -> ${newState}`);
  }

  // 计算回收速度（受重量影响）
  private calculateReelSpeed(): number {
    if (!this.grabbedItem) {
      return this.config.baseReelSpeed;
    }
    // 重量越大，回收越慢，但最少保留30%速度
    const weightFactor = Math.max(0.3, 1 - this.grabbedItem.weight / 100);
    return this.config.baseReelSpeed * weightFactor;
  }

  // 更新钩子末端位置
  private updateHookEnd(): void {
    const rad = (this.angle * Math.PI) / 180;
    this.hookEnd = {
      x: this.position.x + Math.sin(rad) * this.length,
      y: this.position.y + Math.cos(rad) * this.length
    };
  }

  // 检查是否到达边界
  private checkBoundaries(): boolean {
    // 检查是否超出游戏区域（简化处理）
    return (
      this.hookEnd.x < 0 ||
      this.hookEnd.x > 800 ||  // 假设游戏宽度800
      this.hookEnd.y > 600     // 假设游戏高度600
    );
  }

  // 检查与物品的碰撞
  private checkCollision(items: GameItem[]): GameItem | null {
    for (const item of items) {
      const dx = this.hookEnd.x - item.position.x;
      const dy = this.hookEnd.y - item.position.y;
      const distance = Math.sqrt(dx * dx + dy * dy);

      // 简化碰撞检测：使用中心点距离
      if (distance < 20) {  // 钩子碰撞半径
        return item;
      }
    }
    return null;
  }

  // 主更新函数
  public update(deltaTime: number, items: GameItem[]): void {
    const dt = deltaTime / 1000;  // 转换为秒

    switch (this.state) {
      case HookState.SWINGING:
        this.updateSwinging(dt);
        break;

      case HookState.SHOOTING:
        this.updateShooting(dt, items);
        break;

      case HookState.GRABBING:
        // 抓取状态是瞬态，直接切换到回收
        this.transitionTo(HookState.REELING);
        break;

      case HookState.REELING:
        this.updateReeling(dt);
        break;

      case HookState.IDLE:
        // 待命状态，等待开始摆动
        this.transitionTo(HookState.SWINGING);
        break;
    }

    this.updateHookEnd();
  }

  // 摆动状态更新
  private updateSwinging(dt: number): void {
    // 角度摆动
    this.angle += this.config.swingSpeed * this.swingDirection * dt;

    // 边界检查，改变方向
    if (this.angle >= this.config.maxAngle) {
      this.angle = this.config.maxAngle;
      this.swingDirection = -1;
    } else if (this.angle <= this.config.minAngle) {
      this.angle = this.config.minAngle;
      this.swingDirection = 1;
    }
  }

  // 发射状态更新
  private updateShooting(dt: number, items: GameItem[]): void {
    // 增加长度
    this.length += this.config.shootSpeed * dt;

    // 检查边界碰撞
    if (this.checkBoundaries() || this.length >= this.config.maxLength) {
      console.log('[边界] 到达边界或最大长度，开始回收');
      this.transitionTo(HookState.REELING);
      return;
    }

    // 检查物品碰撞
    const hitItem = this.checkCollision(items);
    if (hitItem) {
      this.grabbedItem = hitItem;
      this.transitionTo(HookState.GRABBING);
    }
  }

  // 回收状态更新
  private updateReeling(dt: number): void {
    const reelSpeed = this.calculateReelSpeed();
    this.length -= reelSpeed * dt;

    // 回收完成
    if (this.length <= 0) {
      this.length = 0;
      this.transitionTo(HookState.SWINGING);
    }
  }

  // 玩家操作：发射钩子
  public shoot(): boolean {
    if (this.state !== HookState.SWINGING) {
      console.log('[错误] 当前状态无法发射:', this.state);
      return false;
    }
    this.transitionTo(HookState.SHOOTING);
    return true;
  }

  // 玩家操作：使用炸药（紧急回收）
  public useExplosive(): boolean {
    if (this.state !== HookState.REELING && this.state !== HookState.GRABBING) {
      console.log('[错误] 当前状态无法使用炸药:', this.state);
      return false;
    }

    console.log('[炸药] 使用炸药丢弃物品');
    this.grabbedItem = null;  // 丢弃物品
    // 加速回收
    this.length = 0;
    this.transitionTo(HookState.SWINGING);
    return true;
  }

  // 获取当前状态
  public getState(): HookState {
    return this.state;
  }

  // 获取钩子信息
  public getHookInfo(): {
    state: HookState;
    angle: number;
    length: number;
    position: Position;
    hookEnd: Position;
    grabbedItem: GameItem | null;
  } {
    return {
      state: this.state,
      angle: this.angle,
      length: this.length,
      position: this.position,
      hookEnd: this.hookEnd,
      grabbedItem: this.grabbedItem
    };
  }

  // 重置钩子
  public reset(): void {
    this.length = 0;
    this.grabbedItem = null;
    this.transitionTo(HookState.SWINGING);
  }
}

// ==================== 演示代码 ====================

function runDemo(): void {
  console.log('========== 黄金矿工钩子状态机演示 ==========
');

  // 创建钩子实例
  const hook = new HookStateMachine({
    minAngle: -75,
    maxAngle: 75,
    swingSpeed: 90,
    shootSpeed: 400,
    baseReelSpeed: 200,
    maxLength: 500
  });

  // 创建测试物品
  const testItems: GameItem[] = [
    { id: '1', position: { x: 100, y: 300 }, weight: 10, value: 50, type: 'gold', width: 30, height: 30 },
    { id: '2', position: { x: 200, y: 400 }, weight: 50, value: 20, type: 'rock', width: 40, height: 40 },
    { id: '3', position: { x: 300, y: 350 }, weight: 5, value: 500, type: 'diamond', width: 20, height: 20 }
  ];

  console.log('初始状态:', hook.getState());
  console.log('
--- 模拟游戏循环 ---
');

  // 模拟几个游戏帧
  let frameCount = 0;
  const simulateFrame = () => {
    frameCount++;
    const deltaTime = 50;  // 50ms per frame

    // 第30帧时发射钩子
    if (frameCount === 30) {
      console.log('
>>> 玩家按下发射键');
      hook.shoot();
    }

    // 更新钩子
    hook.update(deltaTime, testItems);

    // 打印状态变化
    if (frameCount % 20 === 0) {
      const info = hook.getHookInfo();
      console.log(`Frame ${frameCount}: ${info.state}, 角度:${info.angle.toFixed(1)}°, 长度:${info.length.toFixed(0)}`);
    }

    // 模拟60帧后停止
    if (frameCount < 100) {
      setTimeout(simulateFrame, 10);
    } else {
      console.log('
========== 演示结束 ==========');
      console.log('最终状态:', hook.getState());
    }
  };

  simulateFrame();
}

// 边界情况测试
function runEdgeCaseTests(): void {
  console.log('
========== 边界情况测试 ==========
');

  const hook = new HookStateMachine();

  // 测试1：非摆动状态发射
  console.log('测试1: 非摆动状态发射');
  hook.shoot();  // 第一次应该成功
  const result = hook.shoot();  // 第二次应该失败
  console.log('第二次发射结果:', result, '(应为false)
');

  // 测试2：重置功能
  console.log('测试2: 重置功能');
  hook.reset();
  console.log('重置后状态:', hook.getState(), '(应为SWINGING)
');

  // 测试3：炸药使用时机
  console.log('测试3: 炸药使用时机');
  const explosiveResult = hook.useExplosive();
  console.log('摆动状态使用炸药:', explosiveResult, '(应为false)');
}

// 运行演示
runDemo();
setTimeout(runEdgeCaseTests, 2000);

// 导出供模块使用
export { HookStateMachine, HookState, type GameItem, type HookConfig, type Position };

