transitionTo(newState) {
  const oldState = this.state;

  try {
    this.listeners[oldState]?.onExit?.();
  } catch (e) {
    console.error(`退出状态${oldState}时出错:`, e);
  }

  this.state = newState;

  try {
    this.listeners[newState]?.onEnter?.();
  } catch (e) {
    console.error(`进入状态${newState}时出错:`, e);
    // 可选：回退到安全状态
    this.state = oldState;
  }
}

